import { test, expect } from '@playwright/test';

test('products API filters by category', async ({ request }) => {
  const res = await request.get('/api/products', { params: { category: 'Bakery' } });
  await expect(res).toBeOK();
  const body = await res.json();
  expect(body.total).toBe(4);
  expect(body.items.map((p: { name: string }) => p.name)).toContain('Sourdough');
});

test('create then delete a todo', async ({ request }) => {
  const created = await request.post('/api/todos', { data: { title: 'Temporary' } });
  expect(created.status()).toBe(201);
  const { id } = await created.json();
  const deleted = await request.delete(`/api/todos/${id}`);
  expect(deleted.status()).toBe(204);
  const again = await request.delete(`/api/todos/${id}`);
  expect(again.status()).toBe(404);
});
